    public function test_init_store_values(): void
    {
        // @Arrange
        $one = new UserPersonalApiKey(
            uid: 'one',
            user: new UserRef('one'),
            name: 'one',
            keyHash: 'one',
            scopes: 'one',
            lastUsedAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            expiresAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            createdAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            enabled: true,
            version: 1,
        );

        // @Act
        $other = $one->toAttributes()->createNewInstance();
        $calculated = UserPersonalApiKey::calculatedFields();

        // @Assert
        $this->assertEquals([ 'lastUsedAt', 'createdAt', 'enabled'], $calculated);
        $this->assertEquals($one->uid(), $other->uid());
        $this->assertEquals($one->getUser(), $other->getUser());
        $this->assertTrue($one->isUserChanged());
        $this->assertEquals($one->getName(), $other->getName());
        $this->assertTrue($one->isNameChanged());
        $this->assertEquals($one->getKeyHash(), $other->getKeyHash());
        $this->assertTrue($one->isKeyHashChanged());
        $this->assertEquals($one->getScopes(), $other->getScopes());
        $this->assertTrue($one->isScopesChanged());
        $this->assertEquals($one->getExpiresAt(), $other->getExpiresAt());
        $this->assertTrue($one->isExpiresAtChanged());
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged());
    }
