        $this->assertEquals('one', $json['name']);
        $this->assertEquals('one', $json['keyHash']);
        $this->assertEquals('one', $json['scopes']);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $json['lastUsedAt']);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $json['expiresAt']);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $json['createdAt']);
        $this->assertEquals(true, $json['enabled']);
        $this->assertEquals(1, $json['version']);
