    public function test_touch_modify(): void
    {
        // @Arrange
        $source = new UserPersonalApiKey(
            uid: 'one',
            user: new UserRef('one'),
            name: 'one',
            keyHash: 'one',
            scopes: 'one',
            lastUsedAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            expiresAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            createdAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            enabled: true,
            version: 1,
        );
        $sourceLastUsedAt = (new \DateTimeImmutable('1980-08-20T14:32:45.123Z'));
        $targetLastUsedAt = (new \DateTimeImmutable('1981-09-06T14:32:45.123Z'));
        $source = $source->withLastUsedAt($sourceLastUsedAt);

        // @Act
        $target = $source->touch($targetLastUsedAt);

        // @Assert
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $source->getLastUsedAt());
        $this->assertEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $target->getLastUsedAt());
        $this->assertNotEquals($sourceLastUsedAt, $target->getLastUsedAt());
    }
    public function test_revoke_modify(): void
    {
        // @Arrange
        $source = new UserPersonalApiKey(
            uid: 'one',
            user: new UserRef('one'),
            name: 'one',
            keyHash: 'one',
            scopes: 'one',
            lastUsedAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            expiresAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            createdAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            enabled: true,
            version: 1,
        );
        $sourceEnabled = true;
        $targetEnabled = false;
        $source = $source->withEnabled($sourceEnabled);

        // @Act
        $target = $source->revoke();

        // @Assert
        $this->assertEquals(true, $source->isEnabled());
        $this->assertEquals($targetEnabled, $target->isEnabled());
        $this->assertNotEquals($sourceEnabled, $target->isEnabled());
    }
